// Calculate this week's Monday to Friday
const now = new Date();
const day = now.getDay();
const monday = new Date(now);
monday.setDate(now.getDate() - (day === 0 ? 6 : day - 1));
monday.setHours(0, 0, 0, 0);

const friday = new Date(monday);
friday.setDate(monday.getDate() + 4);
friday.setHours(23, 59, 59, 999);

return [{ json: {
  week_start: monday.toISOString(),
  week_end: friday.toISOString(),
  week_label: monday.toLocaleDateString('en-IN', { day: 'numeric', month: 'short' }) + ' – ' + friday.toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })
}}];

const events = $input.all().map(i => i.json).filter(e => e.start && e.summary);
const workStart = $('Config').item.json.WORK_START_HOUR;
const workEnd = $('Config').item.json.WORK_END_HOUR;
const focusThreshold = $('Config').item.json.FOCUS_BLOCK_HOURS * 60;

// Group by day
const byDay = {};
events.forEach(e => {
  const start = new Date(e.start.dateTime || e.start.date);
  const end = new Date(e.end.dateTime || e.end.date);
  if (isNaN(start)) return;
  const dayKey = start.toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'short' });
  if (!byDay[dayKey]) byDay[dayKey] = [];
  byDay[dayKey].push({
    title: e.summary,
    start: start.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', hour12: true }),
    end: end.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', hour12: true }),
    duration_mins: Math.round((end - start) / 60000),
    start_hour: start.getHours(),
    end_hour: end.getHours() + end.getMinutes() / 60,
    start_raw: start,
    end_raw: end
  });
});

// Analyse each day
const analysis = [];
for (const [day, meetings] of Object.entries(byDay)) {
  meetings.sort((a, b) => a.start_raw - b.start_raw);
  const totalMeetingMins = meetings.reduce((s, m) => s + m.duration_mins, 0);
  const workMins = (workEnd - workStart) * 60;

  // Find back-to-back (gap < 15 mins)
  let backToBack = 0;
  for (let i = 1; i < meetings.length; i++) {
    const gap = (meetings[i].start_raw - meetings[i-1].end_raw) / 60000;
    if (gap < 15) backToBack++;
  }

  // Find longest focus block
  let maxFocus = 0;
  const slots = [];
  let prev = workStart * 60;
  meetings.forEach(m => {
    const mStart = m.start_hour * 60;
    const gap = mStart - prev;
    if (gap > maxFocus) maxFocus = gap;
    slots.push({ start: prev, end: mStart, gap });
    prev = m.end_hour * 60;
  });
  const finalGap = workEnd * 60 - prev;
  if (finalGap > maxFocus) maxFocus = finalGap;

  analysis.push({
    day,
    meeting_count: meetings.length,
    total_meeting_mins: totalMeetingMins,
    meeting_load_pct: Math.round(totalMeetingMins / workMins * 100),
    back_to_back_count: backToBack,
    longest_focus_mins: Math.round(maxFocus),
    has_focus_block: maxFocus >= focusThreshold,
    meetings_list: meetings.map(m => `${m.start} ${m.title} (${m.duration_mins}m)`).join('\n')
  });
}

const weekLabel = $('Calculate Week Range').item.json.week_label;
const totalMeetings = Object.values(byDay).flat().length;
const daysWithNoFocus = analysis.filter(d => !d.has_focus_block).length;

return [{ json: { analysis, week_label: weekLabel, total_meetings: totalMeetings, days_no_focus: daysWithNoFocus } }];

